import{_ as t,o,c as d,a2 as c}from"./chunks/framework.D5wUhsuj.js";const u=JSON.parse('{"title":"Shared: store, services, utils, types","description":"","frontmatter":{},"headers":[],"relativePath":"shared/core.md","filePath":"shared/core.md","lastUpdated":1785946763000}'),r={name:"shared/core.md"};function a(s,e,i,l,n,h){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="shared-store-services-utils-types" tabindex="-1">Shared: store, services, utils, types <a class="header-anchor" href="#shared-store-services-utils-types" aria-label="Permalink to &quot;Shared: store, services, utils, types&quot;">​</a></h1><p>Каталог: <code>src/shared/</code>.</p><hr><h2 id="types-—-types-index-ts" tabindex="-1">Types — <code>types/index.ts</code> <a class="header-anchor" href="#types-—-types-index-ts" aria-label="Permalink to &quot;Types — `types/index.ts`&quot;">​</a></h2><p>Ключевые типы:</p><table tabindex="0"><thead><tr><th>Тип</th><th>Назначение</th></tr></thead><tbody><tr><td><code>IOptionsInit</code></td><td>Опции <code>mountGigaplanWidget</code></td></tr><tr><td><code>TMode</code></td><td><code>&#39;button&#39; | &#39;embed&#39;</code></td></tr><tr><td><code>TPositionInitButton</code></td><td><code>&#39;left&#39; | &#39;center&#39; | &#39;right&#39;</code></td></tr><tr><td><code>ISettingsState</code> / <code>ISettingsResponse</code></td><td>Состояние и ответ <code>/api/init</code></td></tr><tr><td><code>IStartMessage</code></td><td>Стартовый текст empty-chat + suggested + blocks</td></tr><tr><td><code>IColors</code></td><td><code>brand</code>, <code>brand-second</code>, <code>brand-third</code></td></tr><tr><td><code>TPolicyPopupType</code></td><td>Тип открытого policy popup</td></tr><tr><td><code>TFixedLengthArray</code></td><td>Для <code>pluralWord</code></td></tr></tbody></table><hr><h2 id="settings-store-—-store-settingsstore-ts" tabindex="-1">Settings store — <code>store/settingsStore.ts</code> <a class="header-anchor" href="#settings-store-—-store-settingsstore-ts" aria-label="Permalink to &quot;Settings store — `store/settingsStore.ts`&quot;">​</a></h2><p>Глобальные настройки виджета (не домен чата).</p><p><strong>Хранит:</strong> mode, <code>isAppOpen</code>, <code>isHiddenProject</code>, <code>isFrozen</code>, <code>isMobile</code>, <code>speechAll</code>, policy/agreement тексты, <code>startMessage</code>, позиция кнопки, состояние policy popup.</p><p><strong>Важные actions:</strong></p><table tabindex="0"><thead><tr><th>Action</th><th>Поведение</th></tr></thead><tbody><tr><td><code>openApp</code> / <code>closeApp</code></td><td>Открытие UI; в button — lock/unlock scroll хоста</td></tr><tr><td><code>getBaseDataProject</code></td><td>Вызов init API через settingService</td></tr><tr><td><code>setMode</code></td><td>Режим встраивания</td></tr><tr><td><code>hideProject</code></td><td>Скрыть виджет (404 init)</td></tr><tr><td><code>setFrozen</code></td><td>Заморозка ввода</td></tr><tr><td><code>setPolicyPopupState</code></td><td>Открыть/закрыть PolicyPopup</td></tr><tr><td><code>setSpeechAll</code></td><td>Глобальная озвучка</td></tr><tr><td><code>setIsMobile</code></td><td>Флаг <code>&lt; 1280px</code></td></tr></tbody></table><hr><h2 id="setting-service-—-services-settingservice-ts" tabindex="-1">Setting service — <code>services/settingService.ts</code> <a class="header-anchor" href="#setting-service-—-services-settingservice-ts" aria-label="Permalink to &quot;Setting service — `services/settingService.ts`&quot;">​</a></h2><p><code>getBaseDataProject(complexId?)</code> → <code>POST https://gp.ksdev.ru/api/init</code>.</p><hr><h2 id="utils" tabindex="-1">Utils <a class="header-anchor" href="#utils" aria-label="Permalink to &quot;Utils&quot;">​</a></h2><h3 id="utils-eventbus-ts" tabindex="-1"><code>utils/eventBus.ts</code> <a class="header-anchor" href="#utils-eventbus-ts" aria-label="Permalink to &quot;`utils/eventBus.ts`&quot;">​</a></h3><p><code>mitt()</code>-шина. События: <code>chat:send-message</code>, <code>chat:clear-visual</code>.</p><h3 id="utils-helpers-ts" tabindex="-1"><code>utils/helpers.ts</code> <a class="header-anchor" href="#utils-helpers-ts" aria-label="Permalink to &quot;`utils/helpers.ts`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Функция</th><th>Назначение</th></tr></thead><tbody><tr><td><code>getIsRealDataSber()</code></td><td>Реальный API vs <code>?fake</code></td></tr><tr><td><code>formatPhone</code></td><td>Форматирование телефона</td></tr><tr><td><code>parseBase64Json</code></td><td>Безопасный decode</td></tr><tr><td><code>pluralWord</code></td><td>Склонения («1 квартира / 2 квартиры / 5 квартир»)</td></tr><tr><td><code>loadScript</code></td><td>Динамическая подгрузка <code>&lt;script&gt;</code></td></tr></tbody></table><h3 id="utils-ui-ts-—-класс-uiutils" tabindex="-1"><code>utils/ui.ts</code> — класс <code>UIUtils</code> <a class="header-anchor" href="#utils-ui-ts-—-класс-uiutils" aria-label="Permalink to &quot;`utils/ui.ts` — класс `UIUtils`&quot;">​</a></h3><p>Статические хелперы UI / медиа. Импорт: <code>import { UIUtils } from &#39;@/shared/utils/ui&#39;</code>.</p><h4 id="hextorgb-hex-string-string" tabindex="-1"><code>hexToRgb(hex: string): string</code> <a class="header-anchor" href="#hextorgb-hex-string-string" aria-label="Permalink to &quot;`hexToRgb(hex: string): string`&quot;">​</a></h4><p>Конвертирует HEX-цвет <code>#RRGGBB</code> в строку <code>rgb(r, g, b)</code>.</p><ul><li>Берёт срезы <code>hex.slice(1, 3)</code>, <code>(3, 5)</code>, <code>(5, 7)</code> и парсит как base-16.</li><li>Ожидает формат с <code>#</code> и ровно 6 hex-цифр (короткий <code>#RGB</code> не поддерживается).</li><li>Сейчас в коде проекта <strong>не вызывается</strong> (утилита на будущее / legacy).</li></ul><h4 id="throttle-t-func-t-ms-number" tabindex="-1"><code>throttle&lt;T&gt;(func: T, ms: number)</code> <a class="header-anchor" href="#throttle-t-func-t-ms-number" aria-label="Permalink to &quot;`throttle&lt;T&gt;(func: T, ms: number)`&quot;">​</a></h4><p>Ограничивает частоту вызовов: не чаще одного раза за <code>ms</code> мс.</p><ul><li>Первый вызов в окне выполняется сразу.</li><li>Пока идёт «кульдаун», аргументы последнего вызова сохраняются (<code>savedArgs</code> / <code>savedThis</code>).</li><li>По истечении <code>ms</code> wrapper вызывается ещё раз с сохранёнными аргументами (trailing call).</li><li>Возвращает обёртку с той же сигнатурой <code>Parameters</code> / <code>ReturnType</code>.</li><li>Сейчас в коде проекта <strong>не вызывается</strong>.</li></ul><h4 id="debounce-fun-time-args-any" tabindex="-1"><code>debounce(fun, time): (args) =&gt; any</code> <a class="header-anchor" href="#debounce-fun-time-args-any" aria-label="Permalink to &quot;`debounce(fun, time): (args) =&gt; any`&quot;">​</a></h4><p>Откладывает вызов, пока поток вызовов не «затихнет» на <code>time</code> мс.</p><ul><li>Каждый новый вызов в пределах <code>time</code> сбрасывает предыдущий <code>setTimeout</code>.</li><li>После паузы вызывается <code>fun(args)</code> один раз с последними аргументами.</li><li>В отличие от throttle, <strong>не</strong> выполняет функцию на первом вызове сразу.</li><li>Сейчас в коде проекта <strong>не вызывается</strong>.</li></ul><h4 id="blobtobase64-blob-blob-promise-string" tabindex="-1"><code>blobToBase64(blob: Blob): Promise&lt;string&gt;</code> <a class="header-anchor" href="#blobtobase64-blob-blob-promise-string" aria-label="Permalink to &quot;`blobToBase64(blob: Blob): Promise&lt;string&gt;`&quot;">​</a></h4><p>Читает <code>Blob</code> через <code>FileReader.readAsDataURL</code>.</p><ul><li>Resolve: data-URL вида <code>data:&lt;mime&gt;;base64,…</code>.</li><li>Reject при <code>reader.onerror</code>.</li><li>Сейчас в коде проекта <strong>не вызывается</strong> напрямую.</li></ul><h4 id="encodewav-samples-float32array-samplerate-number-arraybuffer" tabindex="-1"><code>encodeWAV(samples: Float32Array, sampleRate: number): ArrayBuffer</code> <a class="header-anchor" href="#encodewav-samples-float32array-samplerate-number-arraybuffer" aria-label="Permalink to &quot;`encodeWAV(samples: Float32Array, sampleRate: number): ArrayBuffer`&quot;">​</a></h4><p>Собирает PCM WAV (mono, 16-bit) из сэмплов.</p><ol><li>Аллоцирует <code>ArrayBuffer</code> = 44 байта заголовка + <code>samples.length * 2</code>.</li><li>Пишет RIFF/WAVE/<code>fmt </code> (PCM, 1 канал, <code>sampleRate</code>, 16 bit).</li><li>Клипует каждый float в <code>[-1, 1]</code> и пишет как <code>Int16</code> little-endian.</li><li>Возвращает сырой <code>ArrayBuffer</code> (не <code>Blob</code>).</li></ol><p>Используется внутри <code>webmToWav</code>.</p><h4 id="webmtowav-blob-blob-promise-blob" tabindex="-1"><code>webmToWav(blob: Blob): Promise&lt;Blob&gt;</code> <a class="header-anchor" href="#webmtowav-blob-blob-promise-blob" aria-label="Permalink to &quot;`webmToWav(blob: Blob): Promise&lt;Blob&gt;`&quot;">​</a></h4><p>Конвертирует записанный WebM/Opus (или другой decoded blob) в <code>audio/wav</code>.</p><ol><li><code>blob.arrayBuffer()</code> → <code>AudioContext.decodeAudioData</code>.</li><li>Берёт <strong>первый канал</strong> (<code>getChannelData(0)</code>) и <code>sampleRate</code>.</li><li><code>encodeWAV</code> → <code>new Blob([wavBuffer], { type: &#39;audio/wav&#39; })</code>.</li></ol><p><strong>Где:</strong> <code>useAudioRecording</code> — fallback MediaRecorder → WAV перед <code>chatStore.transcribeAudioMessage</code>.</p><h4 id="getwindowwidth-number" tabindex="-1"><code>getWindowWidth(): number</code> <a class="header-anchor" href="#getwindowwidth-number" aria-label="Permalink to &quot;`getWindowWidth(): number`&quot;">​</a></h4><p>Ширина viewport: <code>window.innerWidth</code> или fallback <code>document.documentElement.clientWidth</code>.</p><p><strong>Где:</strong> <code>App.vue</code> — начальное значение и <code>resize</code> → <code>settingsStore.setIsMobile(width &lt; 1280)</code>.</p><h3 id="utils-cookiehelper-ts" tabindex="-1"><code>utils/cookieHelper.ts</code> <a class="header-anchor" href="#utils-cookiehelper-ts" aria-label="Permalink to &quot;`utils/cookieHelper.ts`&quot;">​</a></h3><p><code>getCookie</code> / <code>setCookie</code> / <code>deleteCookie</code> — токены auth.</p><h3 id="utils-bodyscrolllock-ts" tabindex="-1"><code>utils/bodyScrollLock.ts</code> <a class="header-anchor" href="#utils-bodyscrolllock-ts" aria-label="Permalink to &quot;`utils/bodyScrollLock.ts`&quot;">​</a></h3><p><code>lockPageScroll</code> / <code>unlockPageScroll</code> / <code>getIsPageScrollLocked</code> — фиксация <code>body</code> хоста в режиме button.</p><hr><h2 id="icons-—-shared-icons" tabindex="-1">Icons — <code>shared/icons/</code> <a class="header-anchor" href="#icons-—-shared-icons" aria-label="Permalink to &quot;Icons — `shared/icons/`&quot;">​</a></h2><p>SVG-иконки UI. Импорт:</p><ul><li>URL по умолчанию (vite-svg-loader);</li><li><code>?component</code> — как Vue SFC.</li></ul>',54)])])}const p=t(r,[["render",a]]);export{u as __pageData,p as default};
